import re


def parse_duration(s: str) -> int:
    s = s.strip()
    if not s:
        raise ValueError("empty input")

    # Colon forms: mm:ss or hh:mm:ss with integer parts
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3):
            raise ValueError("invalid colon format")
        try:
            nums = [int(p) for p in parts]
        except ValueError:
            raise ValueError("non-integer in colon format")
        if any(n < 0 for n in nums):
            raise ValueError("negative in colon format")
        if len(parts) == 2:
            return nums[0] * 60 + nums[1]
        else:
            return nums[0] * 3600 + nums[1] * 60 + nums[2]

    # Try unit form: sequence of (number)(unit)
    unit_pattern = re.compile(r"(\d+(?:\.\d+)?)([smh])", re.IGNORECASE)
    matches = unit_pattern.findall(s)
    if matches:
        # Ensure the entire string is consumed by the matches
        reconstructed = "".join(f"{num}{unit}" for num, unit in matches)
        if reconstructed.lower() != s.lower():
            raise ValueError("invalid unit format")

        # Ensure units are strictly descending: h > m > s
        order = {"h": 0, "m": 1, "s": 2}
        units = [unit.lower() for _, unit in matches]
        for i in range(len(units) - 1):
            if order[units[i]] >= order[units[i + 1]]:
                raise ValueError("units out of order or duplicated")

        total = 0.0
        for num_str, unit in matches:
            val = float(num_str)
            unit = unit.lower()
            if unit == "h":
                total += val * 3600
            elif unit == "m":
                total += val * 60
            else:
                total += val
        return int(total)

    # Bare number (seconds)
    if re.fullmatch(r"\d+(?:\.\d+)?", s):
        return int(float(s))

    raise ValueError("invalid duration format")

